static float P_C = 0.55f;
static bool netOn = false;
static float P_CN = 0.2f;
static int P_NNSEL = 1;
static float P_CP = 1.0f, P_PT = 0.1f;
static int P_CLIM = 1 << 21;
static float P_DX = 0.3f, P_DO = 0.7f;
static int P_PONDER = 1;
static float P_DE = 0.f;
static float P_FK = 0.02f;
static int P_CT = 32;
static int P_VN = 4;
static float P_LEAF = 1.f;
